function stripTashkeelJS(text) {
  if (!text) return '';
  return text.replace(/[\u064B-\u065F\u0670\u0640]/g, '').trim();
}

function normalizeArabicJS(text) {
  if (!text) return '';
  return stripTashkeelJS(text)
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .trim();
}

function cleanPrimaryAr(arStr) {
  if (!arStr) return '';
  let s = arStr.split('/')[0].split('—')[0];
  s = s.replace(/\s*\([^)]*\)/g, '');
  s = s.replace(/[()]/g, '');
  s = s.replace(/^(?:مصطلح معجمي|صفة متعلقة بـ|حالة أو عملية)\s+/g, '');
  return s.trim() || stripTashkeelJS(arStr);
}

