// Reverse English -> Arabic Name Map
const ENGLISH_TO_ARABIC_NAMES = {
  "mohammed albukeer": "محمد البكير",
  "albukeer": "البكير",
  "mohammed ali": "محمد علي",
  "ibn khaldun": "ابن خلدون",
  "ibn sina": "ابن سينا",
  "avicenna": "ابن سينا",
  "ibn rushd": "ابن رشد",
  "averroes": "ابن رشد"
};
for (const [arK, enV] of Object.entries(ARABIC_TO_ENGLISH_NAMES)) {
  const lowEn = enV.replace(/\s*\([^)]*\)/g, "").trim().toLowerCase();
  if (lowEn && !ENGLISH_TO_ARABIC_NAMES[lowEn]) {
    ENGLISH_TO_ARABIC_NAMES[lowEn] = arK;
  }
}

// Phonetic Transliterator: Arabic -> English (for any unknown family name / proper noun)
function transliterateArabicToEnglishJS(arWord) {
  const clean = stripTashkeelJS(arWord);
  if (!clean) return '';
  if (ARABIC_TO_ENGLISH_NAMES[clean]) return ARABIC_TO_ENGLISH_NAMES[clean];
  let w = clean;
  let prefix = '';
  if (w.startsWith('ال') && w.length > 3) {
    prefix = 'Al-';
    w = w.slice(2);
  } else if (w.startsWith('عبد') && w.length > 4) {
    prefix = 'Abdul-';
    w = w.slice(3);
  }
  const map = {
    'أ': 'a', 'إ': 'i', 'آ': 'a', 'ا': 'a', 'ب': 'b', 'ت': 't', 'ث': 'th',
    'ج': 'j', 'ح': 'h', 'خ': 'kh', 'د': 'd', 'ذ': 'dh', 'ر': 'r', 'ز': 'z',
    'س': 's', 'ش': 'sh', 'ص': 's', 'ض': 'd', 'ط': 't', 'ظ': 'z', 'ع': 'a',
    'غ': 'gh', 'ف': 'f', 'ق': 'q', 'ك': 'k', 'ل': 'l', 'م': 'm', 'ن': 'n',
    'ه': 'h', 'ة': 'a', 'و': 'w', 'ؤ': 'o', 'ي': 'y', 'ى': 'a', 'ئ': 'i', 'ء': ''
  };
  let out = '';
  for (let i = 0; i < w.length; i++) {
    const ch = w[i];
    if (ch === 'و' && i > 0 && i < w.length - 1) out += 'ou';
    else if (ch === 'ي' && i > 0) out += 'i';
    else out += (map[ch] !== undefined ? map[ch] : ch);
  }
  out = out.replace(/aa+/g, 'a').replace(/ii+/g, 'i').replace(/uu+/g, 'u');
  if (out.length > 0) out = out[0].toUpperCase() + out.slice(1);
  return prefix + out;
}

// Phonetic Transliterator: English -> Arabic (for any unknown English proper name)
function transliterateEnglishToArabicJS(enWord) {
  const w = (enWord || '').toLowerCase().trim();
  if (!w) return '';
  if (ENGLISH_TO_ARABIC_NAMES[w]) return ENGLISH_TO_ARABIC_NAMES[w];
  let temp = w;
  if (temp.startsWith('al-')) return 'ال' + transliterateEnglishToArabicJS(temp.slice(3));
  const pairs = [
    ['tion', 'شن'], ['sion', 'جن'], ['sh', 'ش'], ['ch', 'تش'], ['th', 'ث'],
    ['kh', 'خ'], ['gh', 'غ'], ['ph', 'ف'], ['ck', 'ك'], ['qu', 'كو'],
    ['ee', 'ي'], ['oo', 'و'], ['ea', 'ي'], ['ou', 'او'], ['ow', 'او'],
    ['ai', 'اي'], ['ay', 'اي'], ['bb', 'ب'], ['dd', 'د'], ['ff', 'ف'],
    ['ll', 'ل'], ['mm', 'م'], ['nn', 'ن'], ['pp', 'ب'], ['rr', 'ر'], ['ss', 'س'], ['tt', 'ت']
  ];
  for (const [k, v] of pairs) temp = temp.split(k).join(v);
  const cmap = {
    a: 'ا', b: 'ب', c: 'ك', d: 'د', e: 'ي', f: 'ف', g: 'غ', h: 'ه',
    i: 'ي', j: 'ج', k: 'ك', l: 'ل', m: 'م', n: 'ن', o: 'و', p: 'ب',
    q: 'ق', r: 'ر', s: 'س', t: 'ت', u: 'و', v: 'ف', w: 'و', x: 'كس', y: 'ي', z: 'ز'
  };
  let res = '';
  for (let i = 0; i < temp.length; i++) {
    const c = temp[i];
    if (i === 0 && (c === 'a' || c === 'e' || c === 'i')) res += 'أ';
    else if (i === 0 && (c === 'o' || c === 'u')) res += 'أو';
    else res += (cmap[c] || c);
  }
  return res.replace(/([ايو])\1+/g, '$1');
}

