  _addArabicIndexEntry(arRaw, enWord, arFullDisplay, pos, dom, isRoot = false) {
    if (!arRaw || !enWord) return;
    // Strip tashkeel and parenthetical notes
    const unvoc = stripTashkeelJS(arRaw.replace(/\(.*?\)/g, '')).trim();
    if (!unvoc || unvoc.length < 2) return;
    const norm = normalizeArabicJS(unvoc);

    if (!this.arToEnMap.has(unvoc)) {
      this.arToEnMap.set(unvoc, { en: enWord, ar: arFullDisplay, pos, dom, isRoot, synEn: [enWord] });
    } else {
      const ex = this.arToEnMap.get(unvoc);
      if (!ex.synEn.includes(enWord) && ex.synEn.length < 8) ex.synEn.push(enWord);
    }

    if (norm && !this.arNormToEnMap.has(norm)) {
      this.arNormToEnMap.set(norm, { en: enWord, ar: arFullDisplay, pos, dom, isRoot, synEn: [enWord] });
    } else if (norm) {
      const exN = this.arNormToEnMap.get(norm);
      if (!exN.synEn.includes(enWord) && exN.synEn.length < 8) exN.synEn.push(enWord);
    }
  }

