        this.sentenceMapEn.set(sEn.toLowerCase().replace(/[.!?،؟]+$/g, '').trim(), sAr);
        this.sentenceMapAr.set(normalizeArabicJS(sAr.replace(/[.!?،؟]+$/g, '').trim()), sEn);
