    if (literalTranslation && literalTranslation !== naturalTranslation && !alternatives.includes(literalTranslation)) {
      alternatives.push(literalTranslation);
    }

    const resultObj = {
      original_text: raw,
      detected_source_lang: src,
      target_lang: tgt,
      natural_translation: naturalTranslation,
      literal_translation: literalTranslation,
      alternative_translations: alternatives.slice(0, 3),
      token_breakdown: allTokens,
      uncertain_terms: Array.from(new Set(uncertainTerms)),
      word_count: wordsArr.length,
      char_count: raw.length,
      processing_time_ms: Number((performance.now() - t0).toFixed(2)),
      is_online: isOnlineUsed,
      engine_used: engineLabel
    };

