      id: Date.now(),
      query_text: raw,
      result_text: naturalTranslation,
      source_lang: src,
      target_lang: tgt,
      mode: wordsArr.length === 1 ? 'dictionary' : 'translation',
      engine_used: engineLabel,
      processing_ms: resultObj.processing_time_ms,
      created_at: new Date().toISOString().replace('T', ' ').slice(0, 19)
